package uk.zadoss.dorgesh.agility;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

import java.awt.*;

@ConfigGroup(DorgeshKaanAgilityConfig.CONFIG_GROUP)
public interface DorgeshKaanAgilityConfig extends Config {
	public final String CONFIG_GROUP = "dorgeshkaanagilityhelper";


	@ConfigItem(
			keyName = "highlightTurgall",
			name = "Highlight Turgall",
			description = "Highlights Turgall",
			position = 0
	)
	default boolean highlightTurgall() {
		return true;
	}

	@ConfigItem(
			keyName = "turgallColour",
			name = "Turgall Highlight",
			description = "Colour to highlight Turgall with",
			position = 1
	)
	default Color turgallColour() {
		return Color.GREEN;
	}

	@ConfigItem(
			keyName = "highlightComponent",
			name = "Highlight Component",
			description = "Highlights the currently requested components",
			position = 2
	)
	default boolean highlightComponent() {
		return false;
	}

	@ConfigItem(
			keyName = "componentColour",
			name = "Component Highlight",
			description = "Colour to highlight correct component with",
			position = 3
	)
	default Color componentColour() {
		return Color.CYAN;
	}

	@ConfigItem(
			keyName = "textColour",
			name = "Text Colour",
			description = "Colour to highlight correct component text with",
			position = 4
	)
	default Color textHighlightColour() {
		return Color.BLUE;
	}

	@ConfigItem(
			keyName = "showHud",
			name = "Component HUD",
			description = "Show requested components as HUD element",
			position = 5
	)
	default boolean showHud() {
		return true;
	}

	@ConfigItem(
			keyName = "messageFilter",
			name = "Filter obstacle messages",
			description = "Hide obstacle message from the chat",
			position = 6
	)
	default boolean messageFilter() {
		return true;
	}
}

package uk.zadoss.dorgesh.agility;

import lombok.Getter;
import lombok.NonNull;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;
import uk.zadoss.dorgesh.agility.events.RequestItemChanged;
import uk.zadoss.dorgesh.agility.models.Item;

import javax.inject.Inject;
import javax.inject.Singleton;

import java.util.Optional;

@Slf4j
@Singleton
@RequiredArgsConstructor(onConstructor_ = { @Inject })
public final class CourseState {
	private static final int REGION_ID = 10833;

	private final EventBus eventBus;

	@Getter @Setter
	private int currentRegion;

	@Getter @Setter
	private int lastObjectInteraction = -1;

	@Getter @NonNull
	private Optional<Item> heavyItem = Optional.empty();
	@Getter @NonNull
	private Optional<Item> delicateItem = Optional.empty();

	public boolean isOnCourse() {
		return currentRegion == REGION_ID;
	}

	public boolean hasItems() {
		return getHeavyItem().isPresent() && getDelicateItem().isPresent();
	}

	public void reset() {
		resetItems();
	}

	public void resetItems() {
		heavyItem = Optional.empty();
		delicateItem = Optional.empty();
		lastObjectInteraction = -1;

		log.debug("Items reset");
		eventBus.post(new RequestItemChanged());
	}

	public void setItems(Item heavyItem, Item delicateItem) {
		this.heavyItem = Optional.of(heavyItem);
		this.delicateItem = Optional.of(delicateItem);
		lastObjectInteraction = -1;

		log.info("Items set - Heavy: {} | Delicate: {}", heavyItem, delicateItem);
		eventBus.post(new RequestItemChanged());
	}
}

