import uk.zadoss.dorgesh.agility.CourseState;
import uk.zadoss.dorgesh.agility.DorgeshKaanAgilityConfig;
import uk.zadoss.dorgesh.agility.models.GameObject;

import javax.inject.Inject;

import java.awt.*;
import java.util.Optional;

@Slf4j
public final class TurgallOverlay extends Overlay {
	private final DorgeshKaanAgilityConfig config;
	private final CourseState state;

	private Optional<NPC> turgall;

	@Inject
	public TurgallOverlay(DorgeshKaanAgilityConfig config, CourseState state) {
		this.config = config;
		this.state = state;
		turgall = Optional.empty();

		setLayer(OverlayLayer.ABOVE_SCENE);
		setPosition(OverlayPosition.DYNAMIC);
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onNpcSpawned(NpcSpawned event) {
		var npc = event.getNpc();

		if (npc.getId() != GameObject.Turgall.getId())
			return;

		turgall = Optional.of(npc);
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onNpcDespawned(NpcDespawned event) {
		var npc = event.getNpc();

		if (npc.getId() != GameObject.Turgall.getId())
			return;

		turgall = Optional.empty();
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		if (!config.highlightTurgall() || !state.isOnCourse())
			return null;

		turgall.ifPresent(t -> {
			if (t.getConvexHull() == null)
				return;

			OverlayUtil.renderPolygon(graphics, t.getConvexHull(), config.turgallColour());
		});

		return null;
	}
}

package uk.zadoss.dorgesh.agility.processors;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import uk.zadoss.dorgesh.agility.CourseState;
import uk.zadoss.dorgesh.agility.DorgeshKaanAgilityConfig;

import javax.inject.Inject;

import java.util.Set;

@Slf4j
@RequiredArgsConstructor(onConstructor_ = { @Inject })
public final class ChatProcessor {
	private static final Set<String> CHAT_MESSAGES = Set.of(
			"You attempt to balance on the cable...",
			"You swing on the cable...",
			"You swing hand-over-hand across the fallen ladder...",
			"You squeeze through the narrow tunnel.",
			"You squeeze past the jutting wall.",
			"...and safely reach the other side."
	);
	private final Client client;
	private final DorgeshKaanAgilityConfig config;
	private final CourseState state;

	@Subscribe
	@SuppressWarnings("unused")
	public void onChatMessage(ChatMessage event) {
		if (!state.isOnCourse() || !config.messageFilter())
			return;

		if (event.getType() != ChatMessageType.SPAM)
			return;

		if (!CHAT_MESSAGES.contains(event.getMessage()))
			return;

		var chatBuffer = client.getChatLineMap().get(event.getType().getType());

		if (chatBuffer == null)
			return;

		chatBuffer.removeMessageNode(event.getMessageNode());
	}
}

package uk.zadoss.dorgesh.agility.processors;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;
import uk.zadoss.dorgesh.agility.CourseState;
import uk.zadoss.dorgesh.agility.events.CourseEntered;
import uk.zadoss.dorgesh.agility.models.Item;
import uk.zadoss.dorgesh.agility.models.Item.ItemCategory;

import javax.inject.Inject;

@Slf4j @RequiredArgsConstructor(onConstructor_ = { @Inject })
public final class RequestProcessor {
	private final Client client;
	private final CourseState state;

	@Subscribe
	@SuppressWarnings("unused")
	public void onVarbitChanged(VarbitChanged event) {
		if (!state.isOnCourse())
			return;

		var id = event.getVarbitId();

		if (id == VarbitID.DORGESH_AGILITY_PART_HEAVY || id == VarbitID.DORGESH_AGILITY_PART_DELICATE) {
			log.debug("update request for {}", id);
			updateRequest();
		}
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onCourseEntered(CourseEntered event) {
		updateRequest();
	}

	public void updateRequest() {
		var heavy = client.getVarbitValue(VarbitID.DORGESH_AGILITY_PART_HEAVY);
		var delicate = client.getVarbitValue(VarbitID.DORGESH_AGILITY_PART_DELICATE);

		log.info("Items requested - Heavy: {} | Delicate: {}", heavy, delicate);

		if (isNotSet(heavy) || isNotSet(delicate)) {
			state.resetItems();
			return;
		}

		state.setItems(
				Item.fromVarBit(ItemCategory.Heavy, heavy),
				Item.fromVarBit(ItemCategory.Delicate, delicate)
		);
	}

	private boolean isNotSet(int value) {
		return value == 0 || value > 3;
	}
}

package uk.zadoss.dorgesh.agility.processors;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import uk.zadoss.dorgesh.agility.CourseState;
import uk.zadoss.dorgesh.agility.DorgeshKaanAgilityConfig;
import uk.zadoss.dorgesh.agility.models.GameObject;

import javax.inject.Inject;

@Slf4j
@RequiredArgsConstructor(onConstructor_ = { @Inject })
public final class MachineWidgetProcessor {
	private final Client client;
	private final DorgeshKaanAgilityConfig config;
	private final ClientThread clientThread;
	private final CourseState state;

	@Subscribe
	@SuppressWarnings("unused")
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (!state.isOnCourse() || !state.hasItems())
			return;

		state.setLastObjectInteraction(event.getId());
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onWidgetLoaded(WidgetLoaded event) {
		if (!state.isOnCourse() || !state.hasItems())
			return;

		if (event.getGroupId() != InterfaceID.CHATMENU)
			return;

		if (state.getLastObjectInteraction() == GameObject.Boiler.getId() || state.getLastObjectInteraction() == GameObject.Console.getId())
			clientThread.invokeLater(this::DialogOptions);
	}

	private void DialogOptions() {
		var widget = client.getWidget(InterfaceID.Chatmenu.OPTIONS);

		if (widget == null)
			return;

		var lastInteract = state.getLastObjectInteraction();

		for (var child : widget.getDynamicChildren()) {
			log.debug("Child: {} - {} - {}", child, child.getIndex(), child.getText());

			state.getHeavyItem().ifPresent(i -> {
				if (lastInteract != GameObject.Boiler.getId())
					return;

				if (child.getIndex() != i.getDialogOption())
					return;

				highlightOption(child);
			});

			state.getDelicateItem().ifPresent(i -> {
				if (lastInteract != GameObject.Console.getId())
					return;

				if (child.getIndex() != i.getDialogOption())
					return;

				highlightOption(child);
			});
		}
	}

	private void highlightOption(Widget widget) {
		widget.setText(String.format("[%s] %s", widget.getIndex(), widget.getText()));
		widget.setTextColor(config.textHighlightColour().getRGB());
		widget.setOnMouseLeaveListener((JavaScriptCallback)ev -> widget.setTextColor(config.textHighlightColour().getRGB()));
	}
}

package uk.zadoss.dorgesh.agility;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import uk.zadoss.dorgesh.agility.events.CourseEntered;
import uk.zadoss.dorgesh.agility.events.CourseExit;
import uk.zadoss.dorgesh.agility.overlays.BoilerOverlay;
import uk.zadoss.dorgesh.agility.overlays.ConsoleOverlay;
import uk.zadoss.dorgesh.agility.overlays.ItemHud;
import uk.zadoss.dorgesh.agility.overlays.TurgallOverlay;
import uk.zadoss.dorgesh.agility.processors.ChatProcessor;
import uk.zadoss.dorgesh.agility.processors.MachineWidgetProcessor;
import uk.zadoss.dorgesh.agility.processors.RequestProcessor;

import javax.inject.Inject;

@Slf4j
@PluginDescriptor(
		name = "Dorgesh-Kaan Agility Course Helper",
		description = "Provides helpful information for the Dorgesh-Kaan Agility Course",
		tags = { "agility", "course", "helper", "dorgesh-kaan", "dorgesh", "kaan", "dorgeshkaan" }
)
public final class DorgeshKaanAgility extends Plugin {
	@Inject
	private Client client;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private EventBus eventBus;
	@Inject
	private CourseState courseState;
	@Inject
	private TurgallOverlay turgallOverlay;
	@Inject
	private ConsoleOverlay consoleOverlay;
	@Inject
	private BoilerOverlay boilerOverlay;
	@Inject
	private MachineWidgetProcessor partHighlighter;
	@Inject
	private RequestProcessor requestProcessor;
	@Inject
	private ChatProcessor chatProcessor;

	@Inject
	private ItemHud itemHud;

	@Override
	protected void startUp() {
		eventBus.register(consoleOverlay);
		eventBus.register(boilerOverlay);
		eventBus.register(partHighlighter);
		eventBus.register(requestProcessor);
		eventBus.register(turgallOverlay);
		eventBus.register(itemHud);
		eventBus.register(chatProcessor);
		overlayManager.add(turgallOverlay);
		overlayManager.add(consoleOverlay);
		overlayManager.add(boilerOverlay);

		courseState.setCurrentRegion(-1);
		courseState.reset();
	}

	@Override
	protected void shutDown() {
		overlayManager.remove(turgallOverlay);
		overlayManager.remove(consoleOverlay);
		overlayManager.remove(boilerOverlay);
		eventBus.unregister(requestProcessor);
		eventBus.unregister(turgallOverlay);
		eventBus.unregister(consoleOverlay);
		eventBus.unregister(boilerOverlay);
		eventBus.unregister(partHighlighter);
		eventBus.unregister(itemHud);
		eventBus.unregister(chatProcessor);

		itemHud.hideItems();
		courseState.reset();
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onGameTick(GameTick tick) {
		var player = client.getLocalPlayer();

		if (player == null)
			return;

		var previousRegion = courseState.getCurrentRegion();
		courseState.setCurrentRegion(player.getWorldLocation().getRegionID());

		if (previousRegion == courseState.getCurrentRegion())
			return;

		log.debug("Current region id: {}", courseState.getCurrentRegion());

		if (courseState.isOnCourse())
			eventBus.post(new CourseEntered());
		else
			eventBus.post(new CourseExit());
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onCourseEntered(CourseEntered courseExit) {
		log.debug("Entered Dongesh-Kaan Agility Course");
		courseState.reset();
	}

	@Subscribe
	@SuppressWarnings("unused")
	public void onCourseExit(CourseExit courseExit) {
		log.debug("Left Dongesh-Kaan Agility Course");
		courseState.reset();
	}

	@Provides
	@SuppressWarnings("unused")
	DorgeshKaanAgilityConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(DorgeshKaanAgilityConfig.class);
	}
}
